def solve(payload):
    import math
    vertices = payload["vertices"]
    points = vertices[:-1] if len(vertices) > 1 and vertices[0] == vertices[-1] else vertices[:]
    if len(points) < 3:
        return {"error": "too_few_vertices"}
    edges = list(zip(points, points[1:] + points[:1]))
    crosses = [a[0] * b[1] - b[0] * a[1] for a, b in edges]
    twice_area = math.fsum(crosses)
    if abs(twice_area) <= 1e-12:
        return {"error": "degenerate"}
    cx = math.fsum((a[0] + b[0]) * cross for (a, b), cross in zip(edges, crosses)) / (3 * twice_area)
    cy = math.fsum((a[1] + b[1]) * cross for (a, b), cross in zip(edges, crosses)) / (3 * twice_area)
    perimeter = math.fsum(math.hypot(b[0] - a[0], b[1] - a[1]) for a, b in edges)
    return {"area_m2": abs(twice_area) / 2, "centroid_m": [cx, cy], "perimeter_m": perimeter}

